"""Elevacion (m) 0.5 grados, generada de etopo.tiff por elevacion.py.
No editar a mano."""
import array, zlib, base64
W, H = 720, 360
_b = ''
ELEV = array.array('h'); ELEV.frombytes(zlib.decompress(base64.b64decode(_b)))

def elev(lat, lon):
    r = int((90.0 - lat) / 180.0 * H)
    r = 0 if r < 0 else H - 1 if r >= H else r
    c = int((lon + 180.0) / 360.0 * W) % W
    return ELEV[r * W + c]
